1	package wallet
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// ledgerEntryFor 找出指定请求的最后一条指定类型账本记录。
10	func ledgerEntryFor(entries []LedgerEntry, kind LedgerKind, requestID string) (LedgerEntry, bool) {
11		var found LedgerEntry
12		var ok bool
13		for _, e := range entries {
14			if e.Kind == kind && e.RequestID == requestID {
15				found, ok = e, true
16			}
17		}
18		return found, ok
19	}
20	
21	// TestRevokeSessionExpiresDuePendingWithoutQuery：申请已到等待截止时刻但
22	// 从未被查询过，吊销时必须按其原有截止时间进入过期终态，而不是吊销拒绝。
23	func TestRevokeSessionExpiresDuePendingWithoutQuery(t *testing.T) {
24		w, c := setupApproval(t)
25		req, err := w.Apply(approvalApply())
26		if err != nil {
27			t.Fatal(err)
28		}
29		deadline := req.WaitDeadline
30		createdAt := req.CreatedAt
31		before := len(w.Ledger())
32	
33		// 直接越过等待截止时刻，中途不查询这笔申请。
34		c.t = deadline.Add(time.Second)
35		revokeAt := c.t
36		if err := w.RevokeSession("s1"); err != nil {
37			t.Fatal(err)
38		}
39	
40		got, err := w.Request("u1", "r1")
41		if err != nil {
42			t.Fatal(err)
43		}
44		if got.State != RequestExpired {
45			t.Fatalf("state = %v, want expired", got.State)
46		}
47		if got.RejectReason != "" {
48			t.Fatalf("expired by deadline must carry no revoke reason: %q", got.RejectReason)
49		}
50		if got.ApproverAccountID != "" {
51			t.Fatalf("expired request must not record approver: %q", got.ApproverAccountID)
52		}
53		if !got.DecidedAt.Equal(revokeAt) {
54			t.Fatalf("decided at %v, want revoke time %v", got.DecidedAt, revokeAt)
55		}
56		// 提交时间与等待截止时间保持不变。
57		if !got.CreatedAt.Equal(createdAt) || !got.WaitDeadline.Equal(deadline) {
58			t.Fatalf("timing changed: created %v/%v deadline %v/%v", got.CreatedAt, createdAt, got.WaitDeadline, deadline)
59		}
60	
61		// 账本：一条零金额过期留痕，没有拒绝记录。
62		all := w.Ledger()
63		if len(all) != before+1 {
64			t.Fatalf("ledger entries = %d, want %d", len(all), before+1)
65		}
66		e, ok := ledgerEntryFor(all, LedgerExpiration, "r1")
67		if !ok {
68			t.Fatal("missing LedgerExpiration entry")
69		}
70		if e.AccountID != "u1" || e.Amount != 0 {
71			t.Fatalf("expiration entry = %+v", e)
72		}
73		if !e.At.Equal(revokeAt) {
74			t.Fatalf("ledger at %v, want processing (revoke) time %v", e.At, revokeAt)
75		}
76		if countKind(all, LedgerRejection) != 0 {
77			t.Fatal("due pending request must not be recorded as revocation rejection")
78		}
79	
80		// 待审批没有冻结费用：余额与策略累计均不变。
81		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
82			t.Fatalf("balance = %+v, want untouched", bal)
83		}
84		if pv, _ := w.Policy("p-approval"); pv.ReservedTotal != 0 || pv.SpentTotal != 0 {
85			t.Fatalf("policy totals = reserved %d spent %d, want 0/0", pv.ReservedTotal, pv.SpentTotal)
86		}
87	}
88	
89	// TestRevokeSessionDeadlineBoundary：严格早于截止拒绝；等于或晚于截止过期。
90	func TestRevokeSessionDeadlineBoundary(t *testing.T) {
91		cases := []struct {
92			name   string
93			offset time.Duration
94			want   RequestState
95		}{
96			{"strictly before deadline", -time.Second, RequestRejected},
97			{"exactly at deadline", 0, RequestExpired},
98			{"after deadline", time.Second, RequestExpired},
99		}
100		for _, tc := range cases {
101			t.Run(tc.name, func(t *testing.T) {
102				w, c := setupApproval(t)
103				req, err := w.Apply(approvalApply())
104				if err != nil {
105					t.Fatal(err)
106				}
107				c.t = req.WaitDeadline.Add(tc.offset)
108				if err := w.RevokeSession("s1"); err != nil {
109					t.Fatal(err)
110				}
111				got, _ := w.Request("u1", "r1")
112				if got.State != tc.want {
113					t.Fatalf("state = %v, want %v", got.State, tc.want)
114				}
115				if tc.want == RequestExpired {
116					if got.RejectReason != "" || got.ApproverAccountID != "" {
117						t.Fatalf("expired request carries rejection fields: reason %q approver %q", got.RejectReason, got.ApproverAccountID)
118					}
119					if countKind(w.Ledger(), LedgerRejection) != 0 {
120						t.Fatal("must not append rejection for due request")
121					}
122				} else {
123					if got.RejectReason == "" {
124						t.Fatal("revoked-before-deadline request must carry reason")
125					}
126					if got.ApproverAccountID != "" {
127						t.Fatalf("revocation rejection must not fill approver, got %q", got.ApproverAccountID)
128					}
129				}
130			})
131		}
132	}
133	
134	// TestRevokeSessionSameAsQueryOutcome：先查询再吊销与不查询直接吊销，终态、
135	// 原因和账本类型必须一致，差异只在惰性处理记录的决定/账本时间上。
136	func TestRevokeSessionSameAsQueryOutcome(t *testing.T) {
137		setup := func(t *testing.T) (*Wallet, *clock, time.Time) {
138			w, c := setupApproval(t)
139			req, err := w.Apply(approvalApply())
140			if err != nil {
141				t.Fatal(err)
142			}
143			return w, c, req.WaitDeadline
144		}
145	
146		// 路径 A：先查询触发惰性过期，再吊销。
147		wA, cA, deadline := setup(t)
148		cA.t = deadline.Add(time.Second)
149		queriedAt := cA.t // 复制时刻值，避免随后推进时钟时被改写。
150		if r, err := wA.Request("u1", "r1"); err != nil || r.State != RequestExpired {
151			t.Fatalf("query should lazily expire: state=%v err=%v", r.State, err)
152		}
153		cA.t = cA.t.Add(time.Minute)
154		if err := wA.RevokeSession("s1"); err != nil {
155			t.Fatal(err)
156		}
157		rA, _ := wA.Request("u1", "r1")
158	
159		// 路径 B：不查询直接在同一相对时刻吊销。
160		wB, cB, deadlineB := setup(t)
161		cB.t = deadlineB.Add(time.Second + time.Minute)
162		revokeAt := cB
163		if err := wB.RevokeSession("s1"); err != nil {
164			t.Fatal(err)
165		}
166		rB, _ := wB.Request("u1", "r1")
167	
168		if rA.State != RequestExpired || rB.State != RequestExpired {
169			t.Fatalf("states = %v, %v, both want expired", rA.State, rB.State)
170		}
171		if rA.RejectReason != rB.RejectReason || rA.ApproverAccountID != rB.ApproverAccountID {
172			t.Fatalf("rejection fields differ: A(%q,%q) B(%q,%q)",
173				rA.RejectReason, rA.ApproverAccountID, rB.RejectReason, rB.ApproverAccountID)
174		}
175		if !rA.WaitDeadline.Equal(rB.WaitDeadline) || !rA.CreatedAt.Equal(rB.CreatedAt) {
176			t.Fatal("deadline or created time differs")
177		}
178		// 决定/账本时间沿用既有惰性口径：各自在被处理时记录。
179		if !rA.DecidedAt.Equal(queriedAt) || !rB.DecidedAt.Equal(revokeAt.t) {
180			t.Fatalf("decided times = %v, %v, want processing times %v, %v", rA.DecidedAt, rB.DecidedAt, queriedAt, revokeAt.t)
181		}
182		for _, w := range []*Wallet{wA, wB} {
183			if countKind(w.Ledger(), LedgerExpiration) != 1 || countKind(w.Ledger(), LedgerRejection) != 0 {
184				t.Fatalf("ledger kinds wrong: expirations %d rejections %d",
185					countKind(w.Ledger(), LedgerExpiration), countKind(w.Ledger(), LedgerRejection))
186			}
187		}
188	}
189	
190	// TestRevokeSessionMixedStagesPerRequest：同一会话多笔申请处于不同阶段时，
191	// 各笔按自身期限分别得到结果；终态与已预留请求不被改写。
192	func TestRevokeSessionMixedStagesPerRequest(t *testing.T) {
193		w, c := newTestWallet()
194		mustAccount(t, w, "payer", 100)
195		mustAccount(t, w, "u1", 0)
196		mustAccount(t, w, "u2", 0)
197		// 会话与策略窗口都足够长，等待期限只由提交时刻 + 等待时长决定。
198		if _, err := w.CreateSession("s1", "u1", "dev1", c.t.Add(4*time.Hour)); err != nil {
199			t.Fatal(err)
200		}
201		p := approvalPolicy(c)
202		p.EndsAt = c.t.Add(4 * time.Hour)
203		if err := w.SavePolicy(p); err != nil {
204			t.Fatal(err)
205		}
206		apply := func(rid string, fee int64) RequestView {
207			in := approvalApply()
208			in.RequestID = rid
209			in.EstimatedFee = fee
210			req, err := w.Apply(in)
211			if err != nil {
212				t.Fatalf("apply %s: %v", rid, err)
213			}
214			return req
215		}
216	
217		// r1 在 t=0 提交：截止 60s。
218		r1 := apply("r1", 20)
219		// t=30s 再提交 r2：截止 90s。
220		c.t = c.t.Add(30 * time.Second)
221		r2 := apply("r2", 20)
222		if r2.WaitDeadline.Equal(r1.WaitDeadline) {
223			t.Fatalf("r2 deadline %v should be later than r1 %v", r2.WaitDeadline, r1.WaitDeadline)
224		}
225		// r3：待审批后取消（终态）。
226		apply("r3", 20)
227		if _, err := w.Cancel("u1", "r3"); err != nil {
228			t.Fatal(err)
229		}
230		// r4：费用不超门槛，直接预留。
231		apply("r4", 5)
232	
233		// 在 60 秒处吊销：r1 已到截止（60s），r2 未到（90s）。
234		c.t = r1.WaitDeadline
235		if err := w.RevokeSession("s1"); err != nil {
236			t.Fatal(err)
237		}
238	
239		got1, _ := w.Request("u1", "r1")
240		got2, _ := w.Request("u1", "r2")
241		got3, _ := w.Request("u1", "r3")
242		got4, _ := w.Request("u1", "r4")
243		if got1.State != RequestExpired {
244			t.Fatalf("r1 state = %v, want expired (deadline %s <= revoke %s)", got1.State, r1.WaitDeadline, c.t)
245		}
246		if got1.RejectReason != "" {
247			t.Fatalf("r1 must not carry revoke reason: %q", got1.RejectReason)
248		}
249		if got2.State != RequestRejected {
250			t.Fatalf("r2 state = %v, want rejected before its own deadline", got2.State)
251		}
252		if got3.State != RequestCancelled {
253			t.Fatalf("r3 terminal state rewritten: %v", got3.State)
254		}
255		if got4.State != RequestReserved {
256			t.Fatalf("r4 reserved state rewritten: %v", got4.State)
257		}
258	
259		all := w.Ledger()
260		// r1 恰好一条过期记录，r2 恰好一条拒绝记录；r3/r4 不新增状态记录。
261		if e, ok := ledgerEntryFor(all, LedgerExpiration, "r1"); !ok || e.Amount != 0 || e.AccountID != "u1" {
262			t.Fatalf("r1 expiration entry wrong: %+v ok=%v", e, ok)
263		}
264		if e, ok := ledgerEntryFor(all, LedgerRejection, "r2"); !ok || e.Amount != 0 || e.AccountID != "u1" {
265			t.Fatalf("r2 rejection entry wrong: %+v ok=%v", e, ok)
266		}
267		if _, ok := ledgerEntryFor(all, LedgerExpiration, "r2"); ok {
268			t.Fatal("r2 must not have expiration entry")
269		}
270		if _, ok := ledgerEntryFor(all, LedgerRejection, "r1"); ok {
271			t.Fatal("r1 must not have rejection entry")
272		}
273		// 取消记录仍是 r3 唯一的终态记录。
274		if n := countKind(all, LedgerCancellation); n != 1 {
275			t.Fatalf("cancellation entries = %d, want 1", n)
276		}
277	
278		// 余额只反映 r4 的 5 预留；吊销不提前释放、不新增任何资金记录。
279		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 95, Reserved: 5}) {
280			t.Fatalf("balance = %+v, want {95 5}", bal)
281		}
282		if pv, _ := w.Policy("p-approval"); pv.ReservedTotal != 5 || pv.SpentTotal != 0 {
283			t.Fatalf("policy totals = reserved %d spent %d, want 5/0", pv.ReservedTotal, pv.SpentTotal)
284		}
285		// 已预留请求吊销后仍可结算。
286		if _, err := w.Settle("u1", "r4", 5); err != nil {
287			t.Fatalf("settle reserved after revoke: %v", err)
288		}
289	}
290	
291	// TestRevokeSessionDeadlineFromSessionAndPolicy：截止由申请会话到期或策略
292	// 结束先发生时，吊销落在截止之后同样进入过期而非拒绝；已到期会话允许吊销。
293	func TestRevokeSessionDeadlineFromSessionAndPolicy(t *testing.T) {
294		t.Run("session expiry first", func(t *testing.T) {
295			w, c := setupApproval(t)
296			// s1 原本 1 分钟到期，等待时长也是 1 分钟；新建 30 秒到期的会话。
297			if _, err := w.CreateSession("s-short", "u1", "dev1", c.t.Add(30*time.Second)); err != nil {
298				t.Fatal(err)
299			}
300			in := approvalApply()
301			in.SessionID = "s-short"
302			in.RequestID = "rs"
303			req, err := w.Apply(in)
304			if err != nil {
305				t.Fatal(err)
306			}
307			if !req.WaitDeadline.Equal(c.t.Add(30 * time.Second)) {
308				t.Fatalf("deadline = %v, want session expiry", req.WaitDeadline)
309			}
310			// 会话已到期后主动吊销。
311			c.t = c.t.Add(30 * time.Second)
312			if err := w.RevokeSession("s-short"); err != nil {
313				t.Fatalf("revoking expired session should succeed: %v", err)
314			}
315			got, _ := w.Request("u1", "rs")
316			if got.State != RequestExpired || got.RejectReason != "" {
317				t.Fatalf("state = %v reason %q, want plain expiration", got.State, got.RejectReason)
318			}
319		})
320	
321		t.Run("policy end first", func(t *testing.T) {
322			w, c := setupApproval(t)
323			p := approvalPolicy(c)
324			p.ID = "p-short"
325			p.EndsAt = c.t.Add(20 * time.Second)
326			if err := w.SavePolicy(p); err != nil {
327				t.Fatal(err)
328			}
329			in := approvalApply()
330			in.PolicyID = "p-short"
331			in.RequestID = "rp"
332			req, err := w.Apply(in)
333			if err != nil {
334				t.Fatal(err)
335			}
336			if !req.WaitDeadline.Equal(p.EndsAt) {
337				t.Fatalf("deadline = %v, want policy end %v", req.WaitDeadline, p.EndsAt)
338			}
339			c.t = p.EndsAt // 恰为截止时刻：过期而非拒绝。
340			if err := w.RevokeSession("s1"); err != nil {
341				t.Fatal(err)
342			}
343			got, _ := w.Request("u1", "rp")
344			if got.State != RequestExpired || got.ApproverAccountID != "" {
345				t.Fatalf("state = %v approver %q, want plain expiration", got.State, got.ApproverAccountID)
346			}
347		})
348	}
349	
350	// TestRevokeSessionIdempotentAndIsolated：重复吊销不重复留痕；其他会话的
351	// 待审批申请保持不变；会话不存在返回 ErrSessionNotFound 且不改账本。
352	func TestRevokeSessionIdempotentAndIsolated(t *testing.T) {
353		w, c := setupApproval(t)
354	
355		// s1 一笔未到期、s2 一笔未到期。
356		if _, err := w.Apply(approvalApply()); err != nil {
357			t.Fatal(err)
358		}
359		in2 := approvalApply()
360		in2.AccountID, in2.SessionID, in2.DeviceID, in2.RequestID = "u2", "s2", "dev2", "r2"
361		if _, err := w.Apply(in2); err != nil {
362			t.Fatal(err)
363		}
364	
365		c.t = c.t.Add(10 * time.Second)
366		if err := w.RevokeSession("s1"); err != nil {
367			t.Fatal(err)
368		}
369		entriesAfterFirst := len(w.Ledger())
370	
371		// 重复吊销成功，不重复追加状态记录。
372		if err := w.RevokeSession("s1"); err != nil {
373			t.Fatalf("repeat revoke: %v", err)
374		}
375		if len(w.Ledger()) != entriesAfterFirst {
376			t.Fatalf("ledger grew on repeat revoke: %d -> %d", entriesAfterFirst, len(w.Ledger()))
377		}
378	
379		// 其他会话的待审批申请不受影响，仍可被批准。
380		got2, _ := w.Request("u2", "r2")
381		if got2.State != RequestPendingApproval {
382			t.Fatalf("other session request = %v, want still pending", got2.State)
383		}
384		if _, err := w.Approve("u2", "r2", "sa", "dev-approve"); err != nil {
385			t.Fatalf("approve on unaffected session: %v", err)
386		}
387	
388		// 吊销后该会话的新申请被拒绝。
389		if _, err := w.Apply(approvalApply()); !errors.Is(err, ErrSessionRevoked) {
390			t.Fatalf("apply after revoke err = %v, want ErrSessionRevoked", err)
391		}
392	
393		// 不存在的会话：ErrSessionNotFound，账本不变。
394		before := len(w.Ledger())
395		if err := w.RevokeSession("ghost"); !errors.Is(err, ErrSessionNotFound) {
396			t.Fatalf("revoke missing err = %v, want ErrSessionNotFound", err)
397		}
398		if len(w.Ledger()) != before {
399			t.Fatal("ledger changed on revoking unknown session")
400		}
401	}
402	
403	// TestRevokeSessionPriorQueryThenRevokeNoDuplicate：先查询使申请惰性过期后，
404	// 吊销不得再追加任何状态记录。
405	func TestRevokeSessionPriorQueryThenRevokeNoDuplicate(t *testing.T) {
406		w, c := setupApproval(t)
407		if _, err := w.Apply(approvalApply()); err != nil {
408			t.Fatal(err)
409		}
410		c.t = c.t.Add(time.Minute)
411		if r, _ := w.Request("u1", "r1"); r.State != RequestExpired {
412			t.Fatalf("state = %v, want expired", r.State)
413		}
414		before := len(w.Ledger())
415		c.t = c.t.Add(time.Minute)
416		if err := w.RevokeSession("s1"); err != nil {
417			t.Fatal(err)
418		}
419		if len(w.Ledger()) != before {
420			t.Fatalf("ledger grew %d -> %d on revoking already-expired request", before, len(w.Ledger()))
421		}
422		r, _ := w.Request("u1", "r1")
423		if r.State != RequestExpired || r.RejectReason != "" {
424			t.Fatalf("terminal request rewritten: %+v", r)
425		}
426	}
