1097	// TestRestoreRejectsAvailablePlusReservedOverflow 验证可用余额与现存预留
1098	// 合计越过 int64 上限的备份必须被拒绝——即使各请求与策略金额分别合法。
1099	func TestRestoreRejectsAvailablePlusReservedOverflow(t *testing.T) {
1100		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
1101	
1102		cases := []struct {
1103			name       string
1104			fees       map[string]int64
1105			available  int64
1106			reserveDur time.Duration
1107			restoreAt  time.Time
1108		}{
1109			{
1110				name:      "max available plus one reserved, not yet due",
1111				fees:      map[string]int64{"p": 1},
1112				available: math.MaxInt64,
1113				restoreAt: t0,
1114			},
1115			{
1116				name:       "max available plus one reserved, due at restore time",
1117				fees:       map[string]int64{"p": 1},
1118				available:  math.MaxInt64,
1119				reserveDur: time.Minute,
1120				restoreAt:  t0.Add(30 * time.Minute),
1121			},
1122			{
1123				name:      "cross-policy reserved sum pushes total over max",
1124				fees:      map[string]int64{"p1": 1, "p2": 1},
1125				available: math.MaxInt64 - 1,
1126				restoreAt: t0,
1127			},
1128		}
1129		for _, tc := range cases {
1130			t.Run(tc.name, func(t *testing.T) {
1131				data := buildRefundOverflowBackup(t, t0, tc.available, tc.reserveDur, tc.fees)
1132				w2, err := restoreAt(data, tc.restoreAt)
1133				if err == nil {
1134					if w2 != nil {
1135						t.Fatalf("overflow backup restored a wallet")
1136					}
1137					t.Fatalf("overflow backup restored without error")
1138				}
1139				if !errors.Is(err, ErrBackupInvalid) {
1140					t.Fatalf("err = %v, want ErrBackupInvalid", err)
1141				}
1142				if msg := err.Error(); !strings.Contains(msg, "payer") || !strings.Contains(msg, "overflows int64") {
1143					t.Fatalf("error %q must name account and the overflow", msg)
1144				}
1145			})
1146		}
1147	}
