	if err != nil {
		t.Fatal(err)
	}
	return data
}

// corruptCases 基于完整备份做单点损坏，每种都必须被拒绝。
func TestRestoreRejectsCorruptBackups(t *testing.T) {
	w, _ := backupSetup(t)
	good, err := w.Export()
	if err != nil {
		t.Fatal(err)
	}

	type tc struct {
		name   string
		mutate func(m map[string]interface{})
	}
	cases := []tc{
		{"unsupported version", func(m map[string]interface{}) { m["version"] = 2 }},
